import{_ as a,o as t,c as r,a0 as s}from"./chunks/framework.Caz7a20Z.js";const u=JSON.parse('{"title":"一天两篇！DeepSeek 涨价了，明天蹲半价","description":"今天完成了另一篇论文的书写，又用 DeepSeek Harness 搞定了一篇；不过 DeepSeek 涨价后好贵，明天周六打算趁半价时段再推下一篇。","frontmatter":{"title":"一天两篇！DeepSeek 涨价了，明天蹲半价","date":"2026-09-04T00:00:00.000Z","tags":["日记"],"description":"今天完成了另一篇论文的书写，又用 DeepSeek Harness 搞定了一篇；不过 DeepSeek 涨价后好贵，明天周六打算趁半价时段再推下一篇。"},"headers":[],"relativePath":"posts/diary-20260904.md","filePath":"posts/diary-20260904.md","lastUpdated":null}'),o={name:"posts/diary-20260904.md"};function p(n,e,d,i,l,h){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="一天两篇-deepseek-涨价了-明天蹲半价" tabindex="-1">一天两篇！DeepSeek 涨价了，明天蹲半价 <a class="header-anchor" href="#一天两篇-deepseek-涨价了-明天蹲半价" aria-label="Permalink to &quot;一天两篇！DeepSeek 涨价了，明天蹲半价&quot;">​</a></h1><p>今天效率有点离谱，<strong>一天干完两篇论文</strong>，我自己都有点不敢相信 🤯。</p><h2 id="第一篇-另一篇论文写完了" tabindex="-1">第一篇：另一篇论文写完了 <a class="header-anchor" href="#第一篇-另一篇论文写完了" aria-label="Permalink to &quot;第一篇：另一篇论文写完了&quot;">​</a></h2><p>第一条线：<strong>另一篇论文的书写，今天完成了</strong> ✅。</p><p>前言、方法、结果、讨论，一节节往下推，最后总算是凑成了一份完整的稿子。虽然跟之前那篇一样，还是粗糙——细节要抠、逻辑要顺、AI 味要洗——但&quot;写完了&quot;这件事本身就值钱。先有后好，这个套路现在用得越来越顺手了。</p><h2 id="第二篇-deepseek-harness-又拿下一城" tabindex="-1">第二篇：DeepSeek Harness 又拿下一城 <a class="header-anchor" href="#第二篇-deepseek-harness-又拿下一城" aria-label="Permalink to &quot;第二篇：DeepSeek Harness 又拿下一城&quot;">​</a></h2><p>第二条线更爽：<strong>用 DeepSeek Harness 又完成了一篇</strong> 🤖。</p><p>昨天刚上手试水，今天直接拿它推完了一整篇。数据喂进去、思路给它、让它自己往下跑分析再往出吐内容——这套流程跑通之后，效率是真的能翻倍。</p><p>不得不说，这两天论文推进的速度，一半功劳得记在这些工具头上。以前一个人啃，一篇能磨一周；现在有帮手，一天能推两篇。虽然质量还得自己把关，但产能完全不是一个量级。</p><h2 id="但是-deepseek-涨价了-好贵-😭" tabindex="-1">但是：DeepSeek 涨价了，好贵 😭 <a class="header-anchor" href="#但是-deepseek-涨价了-好贵-😭" aria-label="Permalink to &quot;但是：DeepSeek 涨价了，好贵 😭&quot;">​</a></h2><p>爽完之后，账单来了——<strong>DeepSeek 涨价后好贵</strong>。</p><p>之前薅羊毛薅得有多开心，现在看价格就有多肉疼。免费/便宜的时候随便造，一涨价就得开始算着花，每跑一轮心里都在默念&quot;省着点省着点&quot;。</p><p>果然白嫖的快乐都是短暂的，工具一好用，钱包就开始叫苦哈哈。</p><h2 id="明天周六-蹲半价再推一篇" tabindex="-1">明天周六：蹲半价再推一篇 <a class="header-anchor" href="#明天周六-蹲半价再推一篇" aria-label="Permalink to &quot;明天周六：蹲半价再推一篇&quot;">​</a></h2><p>既然涨价了，那就讲点策略——<strong>明天周六，准备趁着半价的时候，再推下一篇</strong> 💰。</p><p>听说周末有半价时段，那正好：明天周六，挑便宜的时候把下一篇啃下来。既省钱又不耽误进度，属于是把&quot;薅羊毛&quot;玩成了&quot;错峰用电&quot;。</p><p>算盘打得挺响，希望明天别睡过头嘿嘿。</p><h2 id="今天就这样" tabindex="-1">今天就这样 <a class="header-anchor" href="#今天就这样" aria-label="Permalink to &quot;今天就这样&quot;">​</a></h2><p>一天两篇，进度条肉眼可见地往前窜。虽然每篇都还得回头打磨，但&quot;都写出来了&quot;这个状态，比什么都让人踏实。</p><p>明天半价时段继续冲，加油 💪！</p>',20)])])}const c=a(o,[["render",p]]);export{u as __pageData,c as default};
